import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { User, Briefcase, X, FileText, ShieldCheck, ArrowLeft, CheckCircle2, Loader2, AlertCircle } from 'lucide-react';

const Register = () => {
  const [showModal, setShowModal] = useState(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [error, setError] = useState(''); // State to handle "Incorrect Data"
  
  const [formData, setFormData] = useState({
    fullName: '',
    orgName: '',
    email: '',
    skills: ''
  });

  const navigate = useNavigate();
  const bgImage = "https://i.pinimg.com/1200x/3d/da/0d/3dda0d2769ba87e3b59597ba56f6548e.jpg";

  // Handle Input Changes
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    if (error) setError(''); // Clear error when user types
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsVerifying(true);
    setError('');

    // --- DATA CHECK LOGIC ---
    setTimeout(() => {
      // 1. Check if Email is valid
      const isEmailValid = formData.email.includes('@') && formData.email.includes('.');
      // 2. Check if Full Name is at least 3 characters
      const isNameValid = formData.fullName.length >= 3;

      if (isEmailValid && isNameValid) {
        // DATA IS CORRECT
        setIsVerifying(false);
        setIsSuccess(true);
        setTimeout(() => navigate('/admin'), 1500);
      } else {
        // DATA IS INCORRECT
        setIsVerifying(false);
        setError('Verification Failed: Please provide a valid Name and Email.');
      }
    }, 2000); // Simulated "Checking" time
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 font-sans bg-cover bg-center bg-no-repeat relative"
      style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.75), rgba(88, 28, 135, 0.65)), url(${bgImage})` }}>
      
      <button onClick={() => navigate('/home')} className="absolute top-8 left-8 z-20 flex items-center gap-2 text-white/70 hover:text-white transition-all font-bold text-xs">
        <ArrowLeft size={18} /> BACK TO LOGIN
      </button>

      {/* Main Selection */}
      {!showModal && (
        <div className="bg-white/10 backdrop-blur-2xl p-3 rounded-[3.5rem] shadow-2xl flex border border-white/10 w-full max-w-xl z-10 animate-in fade-in zoom-in">
          <button onClick={() => setShowModal('student')} className="flex-1 flex flex-col items-center py-12 rounded-[3rem] hover:bg-purple-600/40 group transition-all">
            <User size={40} className="text-purple-400 mb-4 group-hover:text-white" />
            <span className="font-black text-white text-xl uppercase">Student</span>
          </button>
          <button onClick={() => setShowModal('hr')} className="flex-1 flex flex-col items-center py-12 rounded-[3rem] hover:bg-blue-600/40 group transition-all">
            <Briefcase size={40} className="text-blue-400 mb-4 group-hover:text-white" />
            <span className="font-black text-white text-xl uppercase">HR</span>
          </button>
        </div>
      )}

      {/* Registration Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-xl flex items-center justify-center z-50 p-4">
          {!isSuccess ? (
            <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl overflow-hidden">
              <div className={`p-8 text-white flex justify-between items-center ${showModal === 'student' ? 'bg-indigo-600' : 'bg-blue-600'}`}>
                <div className="flex items-center gap-4">
                  <ShieldCheck size={32} />
                  <h2 className="text-2xl font-black uppercase tracking-tighter">Identity Verification</h2>
                </div>
                <button onClick={() => setShowModal(null)} className="p-2 hover:bg-black/20 rounded-full"><X size={24} /></button>
              </div>

              <form onSubmit={handleSubmit} className="p-10 grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* ERROR MESSAGE BOX */}
                {error && (
                  <div className="col-span-2 bg-red-50 border-l-4 border-red-500 p-4 rounded-xl flex items-center gap-3 animate-bounce">
                    <AlertCircle className="text-red-500" />
                    <p className="text-red-700 font-bold text-sm">{error}</p>
                  </div>
                )}

                <input type="text" name="fullName" placeholder="Full Name" className="input-style" value={formData.fullName} onChange={handleChange} required />
                <input type="text" name="orgName" placeholder={showModal === 'student' ? "College Name" : "Company Name"} className="input-style" value={formData.orgName} onChange={handleChange} required />
                <input type="email" name="email" placeholder="Email Address" className="input-style" value={formData.email} onChange={handleChange} required />
                <input type="text" name="skills" placeholder="Skills/Role" className="input-style" value={formData.skills} onChange={handleChange} required />
                
                <button type="submit" disabled={isVerifying} className={`col-span-2 py-5 rounded-2xl font-black text-white shadow-xl flex items-center justify-center gap-3 mt-4 ${isVerifying ? 'bg-amber-500' : (showModal === 'student' ? 'bg-indigo-600' : 'bg-blue-600')}`}>
                  {isVerifying ? <><Loader2 className="animate-spin" /> RUNNING CHECKS...</> : 'LAUNCH VERIFICATION'}
                </button>
              </form>
            </div>
          ) : (
            <div className="text-center animate-in zoom-in duration-500">
              <CheckCircle2 size={80} className="text-green-500 mx-auto mb-6 drop-shadow-lg" />
              <h2 className="text-4xl font-black text-white uppercase tracking-tighter">Identity Verified</h2>
              <p className="text-green-300 font-bold uppercase tracking-widest text-sm">Welcome to the Dashboard</p>
            </div>
          )}
        </div>
      )}

      <style>{`
        .input-style { width: 100%; padding: 1.15rem 1.5rem; background-color: #f8fafc; border: 2px solid #f1f5f9; border-radius: 1.25rem; outline: none; transition: all 0.3s ease; font-weight: 600; }
        .input-style:focus { border-color: #6366f1; box-shadow: 0 10px 25px -5px rgba(99, 102, 241, 0.2); }
      `}</style>
    </div>
  );
};

export default Register;
